import java.util.ArrayList;
import java.util.List;

public class Main {
    // цены, которые укладываются в бюджет
    static List<Integer> affordable(List<Integer> prices, int budget) {
        List<Integer> result = new ArrayList<>();
        for (int price : prices) {
            if (price <= budget) {
                result.add(price);
            }
        }
        return result;
    }

    public static void main(String[] args) {
        System.out.println(affordable(List.of(500, 1500, 999, 2000), 1000));
    }
}

