public class Main {
    // сумма цифр: 1990 -> 1 + 9 + 9 + 0 = 19
    static int digitSum(long n) {
        n = Math.abs(n);
        if (n < 10) {
            return (int) n;
        }
        return (int) (n % 10) + digitSum(n / 10);
    }

    public static void main(String[] args) {
        System.out.println(digitSum(1990));
    }
}

