public class Main {
    // резерв товара: остаток или исключение
    static int reserve(int have, int want) throws StockException {
        if (want <= 0) {
            throw new IllegalArgumentException("количество должно быть больше нуля: " + want);
        }
        if (want > have) {
            throw new StockException(want, have);
